def cmp_semver(a, b):
    def parse(v):
        # Ignore build metadata after '+'
        base = v.split('+', 1)[0]
        if '-' in base:
            core_part, pre_part = base.split('-', 1)
            pre_parts = pre_part.split('.')
        else:
            core_part = base
            pre_parts = None
        major, minor, patch = map(int, core_part.split('.'))
        return (major, minor, patch), pre_parts

    v1_core, v1_pre = parse(a)
    v2_core, v2_pre = parse(b)

    # Compare major, minor, patch numerically
    if v1_core != v2_core:
        return -1 if v1_core < v2_core else 1

    # Pre-release presence logic: version WITH pre-release sorts BEFORE without one
    if v1_pre is None and v2_pre is not None:
        return 1
    if v1_pre is not None and v2_pre is None:
        return -1
    if v1_pre is None and v2_pre is None:
        return 0

    # Compare pre-release identifiers dot-separated left to right
    for p1, p2 in zip(v1_pre, v2_pre):
        is_p1_digit = p1.isdigit()
        is_p2_digit = p2.isdigit()

        if is_p1_digit and is_p2_digit:
            n1, n2 = int(p1), int(p2)
            if n1 != n2:
                return -1 if n1 < n2 else 1
        elif not is_p1_digit and not is_p2_digit:
            if p1 != p2:
                return -1 if p1 < p2 else 1
        else:
            # Numeric identifiers sort before alphanumeric ones
            return -1 if is_p1_digit else 1

    # A longer identifier list wins when all preceding identifiers are equal
    if len(v1_pre) != len(v2_pre):
        return -1 if len(v1_pre) < len(v2_pre) else 1

    return 0
