def parse_range(header, size):
    if not header or not header.startswith("bytes="):
        return None

    try:
        content = header[6:].strip()
        if not content:
            return None

        ranges = []
        for part in content.split(','):
            part = part.strip()
            if '-' not in part:
                return None

            subparts = part.split('-')
            if len(subparts) != 2:
                return None

            s_str, e_str = subparts[0].strip(), subparts[1].strip()

            if not s_str and not e_str:
                return None

            if not s_str:  # -suffix
                suffix = int(e_str)
                start = max(0, size - suffix)
                end = size - 1
                if start < size:
                    ranges.append((start, end))
            elif not e_str:  # start-
                start = int(s_str)
                if start < size:
                    ranges.append((start, size - 1))
            else:  # start-end
                start = int(s_str)
                end = int(e_str)
                if start < size:
                    end = min(end, size - 1)
                    if start <= end:
                        ranges.append((start, end))

        return ranges if ranges else None
    except (ValueError, IndexError):
        return None
