def unified_diff(a, b, context=3):
    n, m = len(a), len(b)
    if a == b:
        return []

    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(m):
            if a[i] == b[j]:
                dp[i+1][j+1] = dp[i][j] + 1
            else:
                dp[i[i+1][j+1]] = max(dp[i][j+1], dp[i+1][j])

    # Correcting the DP table logic for LCS
    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    ops = []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i-1] == b[j-1]:
            ops.append((' ', i-1, j-1, a[i-1]))
            i -= 1
            j -= 1
        elif j > 0 and (i == 0 or dp[i][j-1] >= dp[i-1][j]):
            ops.append(('+', i, j-1, b[j-1]))
            j -= 1
        else:
            ops.append(('-', i-1, j, a[i-1]))
            i -= 1
    ops.reverse()

    # Identify change blocks (contiguous non-' ' operations)
    change_blocks = []
    if ops:
        start = None
        for idx, op in enumerate(ops):
            if op[0] != ' ':
                if start is None:
                    start = idx
            else:
                if start is not None:
                    change_blocks.append((start, idx - 1))
                    start = None
        if start is not None:
            change_blocks.append((start, len(ops) - 1))

    # Expand change blocks with context and merge overlapping hunks
    hunks = []
    for start, end in change_blocks:
        h_start = max(0, start - context)
        h_end = min(len(ops) - 1, end + context)
        hunks.append([h_start, h_end])

    if not hunks:
        return []

    merged_hunks = []
    if hunks:
        hunks.sort()
        curr_start, curr_end = hunks[0]
        for i in range(1, len(hunks)):
            next_start, next_end = hunks[i]
            if next_start <= curr_end + 1:
                curr_end = max(curr_end, next_end)
            else:
                merged_hunks.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged_hunks.append((curr_start, curr_end))

    output = []
    for h_start, h_end in merged_hunks:
        hunk_ops = ops[h_start : h_end + 1]

        a_indices = sorted(list(set(op[1] for op in hunk_ops if op[0] != '+')))
        b_indices = sorted(list(set(op[2] for op in hunk_ops if op[0] != '-')))

        if not a_indices: # Should not happen with valid diffs
            a_start, a_len = 1, 0
        else:
            a_start = a_indices[0] + 1
            a_len = a_indices[-1] - a_indices[0] + 1

        if not b_indices:
            b_start, b_len = 1, 0
        else:
            b_start = b_indices[0] + 1
            b_len = b_indices[-1] - b_indices[0] + 1

        header = f"@@ -{a_start},{a_len} +{b_start},{b_len} @@"
        output.append(header)
        for op in hunk_ops:
            prefix = op[0]
            line = op[3]
            output.append(f"{prefix}{line}")

    return output
