import datetime
import calendar

def next_fire(expr, after):
    try:
        fields = expr.split()
        if len(fields) != 5:
            raise ValueError("Invalid cron expression")

        field_configs = [
            (fields[0], 0, 59),  # minute
            (fields[1], 0, 23),  # hour
            (fields[2], 1, 31),  # day-of-month
            (fields[3], 1, 12),  # month
            (fields[4], 0, 6)    # day-of-week
        ]

        parsed_fields = []
        for f_str, min_v, max_v in field_configs:
            is_star = (f_str == '*')
            vals = set()
            for part in f_str.split(','):
                if not part:
                    raise ValueError("Malformed expression")
                step = 1
                if '/' in part:
                    part, step_s = part.split('/')
                    step = int(step_s)
                    if step <= 0:
                        raise ValueError("Invalid step")

                if '-' in part:
                    start_s, end_s = part.split('-')
                    start, end = int(start_s), int(end_s)
                    if start > end:
                        raise ValueError("Invalid range")
                    for v in range(start, end + 1, step):
                        if not (min_v <= v <= max_v):
                            raise ValueError("Value out of range")
                        vals.add(v)
                elif part == '*':
                    for v in range(min_v, max_v + 1, step):
                        vals.add(v)
                else:
                    v = int(part)
                    if not (min_v <= v <= max_v):
                        raise ValueError("Value out of range")
                    vals.add(v)
            parsed_fields.append((vals, is_star))

        mins, mins_star = parsed_fields[0]
        hours, hours_star = parsed_fields[1]
        doms, doms_star = parsed_fields[2]
        months, months_star = parsed_fields[3]
        dows, dows_star = parsed_fields[4]

        curr_y, curr_m = after.year, after.month

        # Search through months starting from the month of 'after'
        for _ in range(2000): 
            if curr_m in months:
                days_in_month = calendar.monthrange(curr_y, curr_m)[1]
                valid_days = []

                # Day Rule implementation
                if not doms_star and not dows_star:
                    for d in range(1, days_in_month + 1):
                        py_dow = (datetime.date(curr_y, curr_m, d).weekday() + 1) % 7
                        if d in doms or py_dow in dows:
                            valid_days.append(d)
                elif not doms_star:
                    for d in range(1, days_in_month + 1):
                        if d in doms:
                            valid_days.append(d)
                elif not dows_star:
                    for d in range(1, days_in_month + 1):
                        py_dow = (datetime.date(curr_y, curr_m, d).weekday() + 1) % 7
                        if py_dow in dows:
                            valid_days.append(d)
                else:
                    valid_days = list(range(1, days_in_month + 1))

                candidates = []
                for d in valid_days:
                    for h in hours:
                        for m in mins:
                            try:
                                dt = datetime.datetime(curr_y, curr_m, d, h, m)
                                if dt > after:
                                    candidates.append(dt)
                            except ValueError:
                                continue
                if candidates:
                    return min(candidates)

            curr_m += 1
            if curr_m > 12:
                curr_m = 1
                curr_y += 1
        raise ValueError("No match found")
    except (ValueError, IndexError, TypeError):
        raise ValueError("Malformed expression")
