def window_medians(a, k):
    n = len(a)
    if k > n or k <= 0:
        return []

    # Coordinate Compression to use Fenwick Tree (Binary Indexed Tree)
    sorted_unique = sorted(list(set(a)))
    rank = {val: i + 1 for i, val in enumerate(sorted_unique)}
    m = len(sorted_unique)
    bit = [0] * (m + 1)

    def update(i, delta):
        while i <= m:
            bit[i] += delta
            i += i & (-i)

    def find_kth(target):
        idx = 0
        # Binary lifting on the Fenwick Tree to find the k-th element in O(log M)
        for i in range(m.bit_length(), -1, -1):
            next_idx = idx + (1 << i)
            if next_idx <= m and bit[next_idx] < target:
                idx = next_idx
                target -= bit[idx]
        # The element at rank idx + 1 is the first one where prefix sum >= original target
        return sorted_unique[idx]

    res = []
    for i in range(n):
        # Add current element to the window
        update(rank[a[i]], 1)

        # Remove element that has slid out of the window
        if i >= k:
            update(rank[a[i - k]], -1)

        # Once we have a full window, calculate the median
        if i >= k - 1:
            if k % 2 == 1:
                # For odd k, median is the middle element
                res.append(float(find_kth((k + 1) // 2)))
            else:
                # For even k, median is the mean of the two middle elements
                v1 = find_kth(k // 2)
                v2 = find_kth(k // 2 + 1)
                res.append((v1 + v2) / 2.0)

    return res

