                        path.append(key)
                        dfs(next_node, idx + 1, path)
                        path.pop()
            elif char in curr_node:
                path.append(char)
                dfs(curr_node[char], idx + 1, path)
                path.pop()

        dfs(self.root, 0, [])
        return sorted(results)
