def subtract(base, cuts):
    def merge_intervals(intervals):
        if not intervals:
            return []
        # Sort by start time to facilitate merging
        sorted_intervals = sorted(intervals)
        merged = []
        for start, end in sorted_intervals:
            if start >= end:
                continue
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                merged[-1][1] = max(merged[-1][1], end)
        return merged

    # Normalize base and cuts by merging overlapping/touching intervals
    current_intervals = merge_intervals(base)
    merged_cuts = merge_intervals(cuts)

    # Subtract each cut interval from the current set of base intervals
    for c_start, c_end in merged_cuts:
        next_intervals = []
        for b_start, b_end in current_intervals:
            # Case 1: No overlap between the base interval and the cut
            if c_end <= b_start or c_start >= b_end:
                next_intervals.append([b_start, b_end])
            else:
                # Case 2: Overlap exists; potentially split the base interval
                # Part of the base interval before the cut starts
                if b_start < c_start:
                    next_intervals.append([b_start, c_start])
                # Part of the base interval after the cut ends
                if b_end > c_end:
                    next_intervals.append([c_end, b_end])
        current_intervals = next_intervals

    return current_intervals
