        new_dict = {}
        memo[obj_id] = new_dict
        for k, v in obj.items():
            new_key = deep_copy(k, memo)
            new_val = deep_copy(v, memo)
            new_dict[new_key] = new_val
        return new_dict

    # Handle sets
