        return new_set

    # Handle tuples
    if isinstance(obj, tuple):
        # Use a placeholder to handle potential cycles involving the tuple
        memo[obj_id] = None
        new_tuple = tuple(deep_copy(item, memo) for item in obj)
        memo[obj_id] = new_tuple
        return new_tuple

    # Fallback for any other types not explicitly mentioned
    return obj
