import heapq

def topo_lex(graph):
    in_degree = {}
    # Initialize in-degree for all nodes present as keys or successors
    for u, successors in graph.items():
        if u not in in_degree:
            in_degree[u] = 0
        for v in successors:
            in_degree[v] = in_degree.get(v, 0) + 1

    # The set of all nodes is represented by the keys in our in_degree dictionary
    all_nodes_count = len(in_degree)

    # Min-heap to ensure lexicographical order for nodes with 0 in-degree
    heap = [node for node, degree in in_degree.items() if degree == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        # If the current node has successors, decrement their in-degree
        if u in graph:
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    heapq.heappush(heap, v)

    # If result length matches total nodes, no cycle exists
    return result if len(result) == all_nodes_count else None
