        def replacer(match):
            ref = match.group(0)
            return str(self.values.get(ref, 0))
        try:
            expr = re.sub(r'[A-Z]+\d+', replacer, expr)
            # eval is safe here as the input is constrained to numbers and +, -, *
            return float(eval(expr))
        except Exception:
            return 0.0

