    if (a.size !== b.size) return false;
    for (const [k1, v1] of a) {
      let found = false;
      for (const [k2, v2] of b) {
        if (deepEqual(k1, k2, visited) && deepEqual(v1, v2, visited)) {
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
