function debounce(fn, wait, options = {}) {
  let timeout = null;
  let lastArgs = null;
  let lastThis = null;
  let result;
  let isPending = false;

  const leading = !!options.leading;
  const trailing = options.trailing !== false;

  function debounced(...args) {
    lastArgs = args;
    lastThis = this;

    const isInvoking = leading && !timeout;

    if (timeout) clearTimeout(timeout);

    if (isInvoking) {
      result = fn.apply(lastThis, lastArgs);
      isPending = false;
    } else {
      isPending = true;
    }

    timeout = setTimeout(() => {
      if (trailing && isPending) {
        result = fn.apply(lastThis, lastArgs);
      }
      timeout = null;
      isPending = false;
      lastArgs = null;
      lastThis = null;
    }, wait);

    return result;
  }

  debounced.cancel = function() {
    clearTimeout(timeout);
    timeout = null;
    isPending = false;
    lastArgs = null;
    lastThis = null;
  };

  debounced.flush = function() {
    if (timeout) {
      if (trailing && isPending) {
        result = fn.apply(lastThis, lastArgs);
      }
      debounced.cancel();
    }
    return result;
  };

  return debounced;
}

module.exports = debounce;
