  constructor() {
    this.events = new Map();
  }

  on(event, fn) {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    const list = this.events.get(event);
    const item = { fn, once: false };
    list.push(item);
    return () => this.off(event, fn);
  }

  once(event, fn) {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    const list = this.events.get(event);
    const item = { fn, once: true };
    list.push(item);
    return () => this.off(event, fn);
  }

  off(event, fn) {
    const list = this.events.get(event);
    if (!list) return;
    const index = list.findIndex((item) => item.fn === fn);
    if (index !== -1) {
      list.splice(index, 1);
    }
  }

  emit(event, ...args) {
    const list = this.events.get(event);
    if (!list) return 0;

    const snapshot = [...list];
    let invokedCount = 0;
    let firstError = null;

    for (const item of snapshot) {
      if (!list.includes(item)) continue;

      invokedCount++;
      try {
        if (item.once) {
          const idx = list.indexOf(item);
          if (idx !== -1) {
            list.splice(idx, 1);
          }
        }
        item.fn(...args);
      } catch (err) {
        if (!firstError) {
          firstError = err;
        }
      }
    }

    if (firstError) {
      throw firstError;
    }

    return invokedCount;
  }
}

