      const subValues = [];
      for (let i = 0; i < val.length; i++) {
        const res = process(val[i]);
        const offset = subValues.length;
        const remapped = res.text.replace(/\$(\d+)/g, (_, n) => `$${parseInt(n) + offset}`);
        subText += remapped + (i < val.length - 1 ? ', ' : '');
        subValues.push(...res.values);
      }
