function* zipLongest(fill, ...iterables) {
  if (iterables.length === 0) return;

  const iterators = iterables.map((it) => it[Symbol.iterator]());
  const active = new Array(iterators.length).fill(true);

  while (active.some((status) => status)) {
    let anyNewValue = false;
    const row = [];

    for (let i = 0; i < iterators.length; i++) {
      if (active[i]) {
        const { value, done } = iterators[i].next();
        if (done) {
          active[i] = false;
          row.push(fill);
        } else {
          row.push(value);
          anyNewValue = true;
        }
      } else {
        row.push(fill);
      }
    }

    if (anyNewValue) {
      yield row;
    }
  }
}

module.exports = zipLongest;
