 * Parses a query string with PHP/qs-style bracket nesting into an object.
 * @param {string} qs - The query string to parse.
 * @returns {object} The parsed object structure.
 */
function parseQuery(qs) {
  const result = {};
  if (!qs) return result;

  const str = qs.replace(/^\?/, '');
  str.split('&').forEach(pair => {
    let [key, val] = pair.split('=');
    const decode = s => decodeURIComponent(s.replace(/\+/g, ' '));
    const k = decode(key);
    const v = val === undefined ? '' : decode(val);

    const parts = [];
    const regex = /([^\[\]]+)|\[([^\[\]]*)\]/g;
    let m;
    while ((m = regex.exec(k)) !== null) {
      parts.push(m[1] !== undefined ? m[1] : m[2]);
    }

    let curr = result;
    for (let i = 0; i < parts.length; i++) {
      const p = parts[i];
      const isLast = i === parts.length - 1;

      if (isLast) {
        if (p === '') {
          curr.push(v);
        } else {
          if (curr[p] !== undefined) {
            if (!Array.isArray(curr[p])) curr[p] = [curr[p]];
            curr[p].push(v);
          } else {
            curr[p] = v;
          }
        }
      } else {
        const nextP = parts[i + 1];
        const isNextArray = nextP === '' || (!isNaN(nextP) && nextP !== '');

        if (curr[p] === undefined) {
          curr[p] = isNextArray ? [] : {};
        } else if (isNextArray && !Array.isArray(curr[p])) {
          curr[p] = [curr[p]];
        } else if (!isNextArray && typeof curr[p] !== 'object') {
          curr[p] = {};
        }
        curr = curr[p];
      }
    }
  });

  return result;
}

/**
 * Builds a query string from an object with PHP/qs-style bracket nesting.
 * @param {object} obj - The object to serialize.
 * @returns {string} The resulting query string.
 */
function buildQuery(obj) {
  const pairs = [];

  function flatten(curr, path) {
    if (typeof curr !== 'object' || curr === null) {
      pairs.push({ path, value: curr });
      return;
    }

    const keys = Object.keys(curr).sort();
    for (const k of keys) {
      const newPath = path ? `${path}[${k}]` : k;
      flatten(curr[k], newPath);
    }
