  return pairs
    .sort((a, b) => a.path.localeCompare(b.path))
    .map(p => {
      const encodedVal = encodeURIComponent(String(p.value)).replace(/%20/g, '+');
      return `${p.path}=${encodedVal}`;
    })
    .join('&');
