export function defineRoutes<T extends Record<string, string>>(
  routes: T
): {
  [K in keyof T]: T[K] extends infer P
    ? P extends string
      ? ParamsFromTemplate<P> extends void
        ? () => string
        : (params: ParamsFromTemplate<P> & { [K in keyof ParamsFromTemplate<P>]?: never }) => string
      : never
    : never;
} {
  const result = {} as any;

  for (const key in routes) {
    const template = routes[key];
    result[key] = (...args: any[]) => {
      let path = template;
      if (args.length > 0 && typeof args[0] === 'object' && args[0] !== null) {
        const params = args[0];
        for (const k in params) {
          path = path.split(`:${k}`).join(String(params[k]));
        }
      }
      return path;
    };
  }

  return result;
}
